/**
 * errors.mjs -- Mark objects and the YAML error hierarchy.
 *
 * Faithful port of PyYAML's `yaml/error.py`.  `Mark.buffer` is an array of
 * single code-point strings (see reader.mjs) so that indexes and column
 * numbers line up with CPython's code-point based strings.
 */

const LINE_BREAKS = '\0\r\n\x85  ';

function isBreakOrNull(ch) {
  return ch !== undefined && LINE_BREAKS.indexOf(ch) !== -1;
}

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && !isBreakOrNull(this.buffer[start - 1])) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && !isBreakOrNull(this.buffer[end])) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = this.buffer.slice(start, end).join('');
    return ' '.repeat(indent) + head + snippet + tail + '\n'
      + ' '.repeat(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.name = 'YAMLError';
    this.pyType = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super('');
    this.context = context === undefined ? null : context;
    this.contextMark = contextMark === undefined ? null : contextMark;
    this.problem = problem === undefined ? null : problem;
    this.problemMark = problemMark === undefined ? null : problemMark;
    this.note = note === undefined ? null : note;
    this.name = 'MarkedYAMLError';
    this.pyType = 'yaml.error.MarkedYAMLError';
    this.message = this.render();
  }

  render() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null
      && (this.problem === null || this.problemMark === null
        || this.contextMark.name !== this.problemMark.name
        || this.contextMark.line !== this.problemMark.line
        || this.contextMark.column !== this.problemMark.column)) {
      lines.push(String(this.contextMark));
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(String(this.problemMark));
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }

  toString() {
    return this.render();
  }
}

export class ReaderError extends YAMLError {
  constructor(name, position, character, encoding, reason) {
    super('');
    this.streamName = name;
    this.position = position;
    this.character = character;
    this.encoding = encoding;
    this.reason = reason;
    this.name = 'ReaderError';
    this.pyType = 'yaml.reader.ReaderError';
    this.message = `unacceptable character #x${this.character.codePointAt(0).toString(16)}: ${reason}\n`
      + `  in "${name}", position ${position}`;
  }
  toString() { return this.message; }
}

export class ScannerError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.name = 'ScannerError';
    this.pyType = 'yaml.scanner.ScannerError';
  }
}

export class ParserError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.name = 'ParserError';
    this.pyType = 'yaml.parser.ParserError';
  }
}

export class ComposerError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.name = 'ComposerError';
    this.pyType = 'yaml.composer.ComposerError';
  }
}

export class ConstructorError extends MarkedYAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(context, contextMark, problem, problemMark, note);
    this.name = 'ConstructorError';
    this.pyType = 'yaml.constructor.ConstructorError';
  }
}

export class EmitterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'EmitterError';
    this.pyType = 'yaml.emitter.EmitterError';
  }
}

export class SerializerError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'SerializerError';
    this.pyType = 'yaml.serializer.SerializerError';
  }
}

export class RepresenterError extends YAMLError {
  constructor(message) {
    super(message);
    this.name = 'RepresenterError';
    this.pyType = 'yaml.representer.RepresenterError';
  }
}

