input.content:
/**
 * chars.mjs -- character classification helpers shared by the reader,
 * scanner and emitter.
 *
 * Every predicate takes a single code-point string (or `undefined` for
 * "past the end of the stream") so the whole pipeline can work on arrays of
 * code points, matching CPython's code-point based `str`.
 *
 * The five characters PyYAML treats as line breaks are LF, CR, NEL (U+0085),
 * LINE SEPARATOR (U+2028) and PARAGRAPH SEPARATOR (U+2029).  '\0' stands for
 * end-of-stream in the reader's buffer.
 */

export const NUL = '�';
export const LF = '
';
export const CR = '';
export const NEL = '';
export const LS = ' ';
export const PS = ' ';
export const TAB = '	';
export const SPACE = ' ';
export const BOM = '﻿';

/** The line-break characters, as a plain string usable with indexOf(). */
export const BREAKS = LF + CR + NEL + LS + PS;
/** Line breaks plus the end-of-stream sentinel. */
export const BREAKS_NUL = NUL + BREAKS;
/** Line breaks plus the end-of-stream sentinel, space and tab. */
export const BREAKS_NUL_SPACE_TAB = NUL + SPACE + TAB + BREAKS;

const DIGITS = '0123456789';
const LOWER = 'abcdefghijklmnopqrstuvwxyz';
const UPPER = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const HEX = DIGITS + 'abcdefABCDEF';

export function isBreak(ch) {
  return ch !== undefined && BREAKS.indexOf(ch) !== -1;
}

export function isBreakOrNul(ch) {
  return ch === undefined || BREAKS_NUL.indexOf(ch) !== -1;
}

export function isBlank(ch) {
  return ch === SPACE || ch === TAB;
}

/** space, tab, line break or end of stream */
export function isBlankOrBreakOrNul(ch) {
  return ch === undefined || BREAKS_NUL_SPACE_TAB.indexOf(ch) !== -1;
}

export function isDigit(ch) {
  return ch !== undefined && ch.length === 1 && DIGITS.indexOf(ch) !== -1;
}

export function isHex(ch) {
  return ch !== undefined && ch.length === 1 && HEX.indexOf(ch) !== -1;
}

export function isAlphaNumericOrDashUnderscore(ch) {
  if (ch === undefined || ch.length !== 1) return false;
  return DIGITS.indexOf(ch) !== -1 || LOWER.indexOf(ch) !== -1
    || UPPER.indexOf(ch) !== -1 || ch === '-' || ch === '_';
}

/** Convert a JS string into an array of single code-point strings. */
export function toCodePoints(str) {
  return Array.from(str);
}

/** Numeric value of a hexadecimal digit. */
export function hexValue(ch) {
  const code = ch.codePointAt(0);
  if (code >= 0x30 && code <= 0x39) return code - 0x30;
  if (code >= 0x61 && code <= 0x66) return code - 0x61 + 10;
  if (code >= 0x41 && code <= 0x46) return code - 0x41 + 10;
  return -1;
}

