/**
 * reader.mjs -- character stream with position tracking.
 *
 * Port of PyYAML's `yaml/reader.py` for the "unicode string" input case,
 * which is the only one this program needs.  The whole document lives in
 * `buffer` as an array of code points terminated by a NUL sentinel, so
 * `update()` is unnecessary.
 */

import { Mark, ReaderError } from './errors.mjs';
import { NUL, LF, CR, NEL, LS, PS, BOM, toCodePoints } from './chars.mjs';

const STREAM_NAME = '<unicode string>';

/** The YAML 1.1 printable character set (PyYAML's NON_PRINTABLE inverse). */
function isPrintable(code) {
  if (code === 0x09 || code === 0x0a || code === 0x0d) return true;
  if (code >= 0x20 && code <= 0x7e) return true;
  if (code === 0x85) return true;
  if (code >= 0xa0 && code <= 0xd7ff) return true;
  if (code >= 0xe000 && code <= 0xfffd) return true;
  if (code >= 0x10000 && code <= 0x10ffff) return true;
  return false;
}

export class Reader {
  constructor(stream) {
    this.name = STREAM_NAME;
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.pointer = 0;
    const points = toCodePoints(stream);
    this.checkPrintable(points);
    points.push(NUL);
    this.buffer = points;
  }

  checkPrintable(points) {
    for (let i = 0; i < points.length; i += 1) {
      const code = points[i].codePointAt(0);
      if (!isPrintable(code)) {
        throw new ReaderError(this.name, i, code, 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? NUL : ch;
  }

  /** The next `length` characters as a plain string. */
  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    let remaining = length;
    while (remaining > 0) {
      const ch = this.buffer[this.pointer];
      if (ch === undefined) break;
      this.pointer += 1;
      this.index += 1;
      if (ch === LF || ch === NEL || ch === LS || ch === PS
        || (ch === CR && this.buffer[this.pointer] !== LF)) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== BOM) {
        this.column += 1;
      }
      remaining -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

