/**
 * events.mjs -- parser / emitter event types.
 *
 * Port of PyYAML's `yaml/events.py`.  Like tokens, events carry a string
 * `id` rather than relying on class identity.
 */

export const E = {
  STREAM_START: 'StreamStart',
  STREAM_END: 'StreamEnd',
  DOCUMENT_START: 'DocumentStart',
  DOCUMENT_END: 'DocumentEnd',
  ALIAS: 'Alias',
  SCALAR: 'Scalar',
  SEQUENCE_START: 'SequenceStart',
  SEQUENCE_END: 'SequenceEnd',
  MAPPING_START: 'MappingStart',
  MAPPING_END: 'MappingEnd',
};

export class Event {
  constructor(id, startMark, endMark, extra) {
    this.id = id;
    this.startMark = startMark === undefined ? null : startMark;
    this.endMark = endMark === undefined ? null : endMark;
    if (extra) Object.assign(this, extra);
  }
}

export function streamStart(startMark, endMark, encoding) {
  return new Event(E.STREAM_START, startMark, endMark, { encoding: encoding || null });
}

export function streamEnd(startMark, endMark) {
  return new Event(E.STREAM_END, startMark, endMark);
}

export function documentStart(startMark, endMark, explicit, version, tags) {
  return new Event(E.DOCUMENT_START, startMark, endMark, {
    explicit: explicit === undefined ? null : explicit,
    version: version === undefined ? null : version,
    tags: tags === undefined ? null : tags,
  });
}

export function documentEnd(startMark, endMark, explicit) {
  return new Event(E.DOCUMENT_END, startMark, endMark, {
    explicit: explicit === undefined ? null : explicit,
  });
}

export function alias(anchor, startMark, endMark) {
  return new Event(E.ALIAS, startMark, endMark, { anchor });
}

export function scalar(anchor, tag, implicit, value, startMark, endMark, style) {
  return new Event(E.SCALAR, startMark, endMark, {
    anchor, tag, implicit, value,
    style: style === undefined ? null : style,
  });
}

export function sequenceStart(anchor, tag, implicit, startMark, endMark, flowStyle) {
  return new Event(E.SEQUENCE_START, startMark, endMark, {
    anchor, tag, implicit,
    flowStyle: flowStyle === undefined ? null : flowStyle,
  });
}

export function sequenceEnd(startMark, endMark) {
  return new Event(E.SEQUENCE_END, startMark, endMark);
}

export function mappingStart(anchor, tag, implicit, startMark, endMark, flowStyle) {
  return new Event(E.MAPPING_START, startMark, endMark, {
    anchor, tag, implicit,
    flowStyle: flowStyle === undefined ? null : flowStyle,
  });
}

export function mappingEnd(startMark, endMark) {
  return new Event(E.MAPPING_END, startMark, endMark);
}

export function isCollectionStart(ev) {
  return ev.id === E.SEQUENCE_START || ev.id === E.MAPPING_START;
}

export function isCollectionEnd(ev) {
  return ev.id === E.SEQUENCE_END || ev.id === E.MAPPING_END;
}

export function isNodeEvent(ev) {
  return ev.id === E.ALIAS || ev.id === E.SCALAR
    || ev.id === E.SEQUENCE_START || ev.id === E.MAPPING_START;
}

