/**
 * pyrepr.mjs -- Python `repr()` / `str()` semantics needed by the port.
 *
 * Two separate jobs live here:
 *   * `reprChar` / `reprString` -- used inside scanner/parser error messages,
 *     which interpolate `%r` of a character.
 *   * `floatRepr` / `intRepr` -- used by the representer, which relies on
 *     `repr(float)` and `str(int)` to produce scalar text.
 */

import {
  BACKSLASH, DQUOTE, SQUOTE, TAB, LF, CR, hexPad,
} from './chars.mjs';

/** Characters CPython's repr() escapes with a short form. */
function shortEscape(code) {
  if (code === 0x09) return BACKSLASH + 't';
  if (code === 0x0a) return BACKSLASH + 'n';
  if (code === 0x0d) return BACKSLASH + 'r';
  return null;
}

/**
 * True when CPython's repr() would print the code point literally.  We treat
 * everything outside Latin-1 as printable, which is right for every character
 * that can reach an error message here, and escape the C0/C1 ranges plus the
 * soft hyphen, which is what Python does.
 */
function isReprPrintable(code) {
  if (code < 0x20) return false;
  if (code === 0x7f) return false;
  if (code >= 0x80 && code <= 0xa0) return false;
  if (code === 0xad) return false;
  return true;
}

/** Python's repr() for a str. */
export function reprString(s) {
  const chars = Array.from(s);
  let quote = SQUOTE;
  if (s.indexOf(SQUOTE) !== -1 && s.indexOf(DQUOTE) === -1) quote = DQUOTE;
  let out = quote;
  for (const ch of chars) {
    const code = ch.codePointAt(0);
    if (ch === quote || ch === BACKSLASH) {
      out += BACKSLASH + ch;
      continue;
    }
    const short = shortEscape(code);
    if (short !== null) {
      out += short;
      continue;
    }
    if (isReprPrintable(code)) {
      out += ch;
    } else if (code <= 0xff) {
      out += BACKSLASH + 'x' + hexPad(code, 2);
    } else if (code <= 0xffff) {
      out += BACKSLASH + 'u' + hexPad(code, 4);
    } else {
      out += BACKSLASH + 'U' + hexPad(code, 8);
    }
  }
  return out + quote;
}

/** Python's repr() for a one-character str (what `%r` produces in messages). */
export function reprChar(ch) {
  return reprString(ch);
}

/** Python's str() for an int, given a BigInt. */
export function intRepr(value) {
  return value.toString();
}

/**
 * Python's repr() for a finite float.
 *
 * CPython formats with the shortest round-tripping digit string and switches
 * to exponential notation when the decimal point position `decpt` satisfies
 * `decpt <= -4 || decpt > 16`.  Fixed notation always keeps at least one
 * fractional digit; exponential notation does not add a `.0`, and the
 * exponent is signed with at least two digits.
 */
export function floatRepr(value) {
  if (value === 0) {
    return (1 / value === -Infinity) ? '-0.0' : '0.0';
  }
  const negative = value < 0;
  const abs = negative ? -value : value;

  // toExponential() with no argument yields the shortest digit string that
  // uniquely identifies the double -- the same digits CPython's repr uses.
  const exponential = abs.toExponential();
  const eIndex = exponential.indexOf('e');
  const mantissa = exponential.slice(0, eIndex);
  const exponent = Number(exponential.slice(eIndex + 1));
  const digits = mantissa.replace('.', '');
  const decpt = exponent + 1;

  let out;
  if (decpt <= -4 || decpt > 16) {
    out = digits.slice(0, 1);
    if (digits.length > 1) out += '.' + digits.slice(1);
    const expAbs = Math.abs(decpt - 1);
    let expDigits = String(expAbs);
    if (expDigits.length < 2) expDigits = '0' + expDigits;
    out += 'e' + (decpt - 1 < 0 ? '-' : '+') + expDigits;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + out : out;
}

export { TAB, LF, CR };

