/**
 * scanner.mjs -- YAML tokenizer.
 *
 * Faithful port of PyYAML's `yaml/scanner.py`.  Behaviour, including the
 * wording and position of every error, is preserved so the JS port reports
 * the same diagnostics as the Python original.
 */

import { Reader } from './reader.mjs';
import { ScannerError } from './errors.mjs';
import { T, token } from './tokens.mjs';
import { reprChar } from './pyrepr.mjs';
import {
  NUL, SPACE, TAB, LF, CR, NEL, LS, PS, BOM, BACKSLASH, DQUOTE, SQUOTE,
  BREAKS, isAlphaNumeric, isDigit, isHexDigit,
} from './chars.mjs';

/** '\0 \t\r\n\x85  ' */
const NULL_BL_T_LINEBR = NUL + SPACE + TAB + BREAKS;
/** '\0 \r\n\x85  ' (no tab) */
const NULL_BL_LINEBR = NUL + SPACE + BREAKS;
/** '\0\r\n\x85  ' */
const NULL_OR_LINEBR = NUL + BREAKS;

const ESCAPE_REPLACEMENTS = new Map([
  ['0', NUL],
  ['a', String.fromCharCode(0x07)],
  ['b', String.fromCharCode(0x08)],
  ['t', TAB],
  [TAB, TAB],
  ['n', LF],
  ['v', String.fromCharCode(0x0b)],
  ['f', String.fromCharCode(0x0c)],
  ['r', CR],
  ['e', String.fromCharCode(0x1b)],
  [SPACE, SPACE],
  [DQUOTE, DQUOTE],
  [BACKSLASH, BACKSLASH],
  ['/', '/'],
  ['N', NEL],
  ['_', String.fromCharCode(0xa0)],
  ['L', LS],
  ['P', PS],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

const URI_EXTRA_CHARS = '-;/?:@&=+$,_.!~*' + SQUOTE + '()[]%';

function inSet(set, ch) {
  return ch !== undefined && ch.length === 1 && set.indexOf(ch) !== -1;
}

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

export class Scanner {
  constructor(stream) {
    this.reader = new Reader(stream);
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    /** Map from flow level to SimpleKey. */
    this.possibleSimpleKeys = new Map();
    this.fetchStreamStart();
  }

  // --- reader delegation -------------------------------------------------

  peek(index = 0) { return this.reader.peek(index); }
  prefix(length = 1) { return this.reader.prefix(length); }
  forward(length = 1) { this.reader.forward(length); }
  getMark() { return this.reader.getMark(); }
  get column() { return this.reader.column; }
  get line() { return this.reader.line; }
  get index() { return this.reader.index; }

  // --- public token API -------------------------------------------------

  checkToken(...choices) {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      if (choices.length === 0) return true;
      for (const choice of choices) {
        if (this.tokens[0].id === choice) return true;
      }
    }
    return false;
  }

  peekToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    return this.tokens.length > 0 ? this.tokens[0] : null;
  }

  getToken() {
    while (this.needMoreTokens()) this.fetchMoreTokens();
    if (this.tokens.length > 0) {
      this.tokensTaken += 1;
      return this.tokens.shift();
    }
    return null;
  }

  needMoreTokens() {
    if (this.done) return false;
    if (this.tokens.length === 0) return true;
    this.stalePossibleSimpleKeys();
    return this.nextPossibleSimpleKey() === this.tokensTaken;
  }

  fetchMoreTokens() {
    this.scanToNextToken();
    this.stalePossibleSimpleKeys();
    this.unwindIndent(this.column);
    const ch = this.peek();
    if (ch === NUL) return this.fetchStreamEnd();
    if (ch === '%' && this.checkDirective()) return this.fetchDirective();
    if (ch === '-' && this.checkDocumentStart()) return this.fetchDocumentStart();
    if (ch === '.' && this.checkDocumentEnd()) return this.fetchDocumentEnd();
    if (ch === '[') return this.fetchFlowSequenceStart();
    if (ch === '{') return this.fetchFlowMappingStart();
    if (ch === ']') return this.fetchFlowSequenceEnd();
    if (ch === '}') return this.fetchFlowMappingEnd();
    if (ch === ',') return this.fetchFlowEntry();
    if (ch === '-' && this.checkBlockEntry()) return this.fetchBlockEntry();
    if (ch === '?' && this.checkKey()) return this.fetchKey();
    if (ch === ':' && this.checkValue()) return this.fetchValue();
    if (ch === '*') return this.fetchAlias();
    if (ch === '&') return this.fetchAnchor();
    if (ch === '!') return this.fetchTag();
    if (ch === '|' && this.flowLevel === 0) return this.fetchLiteral();
    if (ch === '>' && this.flowLevel === 0) return this.fetchFolded();
    if (ch === SQUOTE) return this.fetchSingle();
    if (ch === DQUOTE) return this.fetchDouble();
    if (this.checkPlain()) return this.fetchPlain();
    throw new ScannerError('while scanning for the next token', null,
      'found character ' + reprChar(ch) + ' that cannot start any token',
      this.getMark());
  }

  // --- simple keys ------------------------------------------------------

  nextPossibleSimpleKey() {
    let minTokenNumber = null;
    for (const key of this.possibleSimpleKeys.values()) {
      if (minTokenNumber === null || key.tokenNumber < minTokenNumber) {
        minTokenNumber = key.tokenNumber;
      }
    }
    return minTokenNumber;
  }

  stalePossibleSimpleKeys() {
    for (const level of Array.from(this.possibleSimpleKeys.keys())) {
      const key = this.possibleSimpleKeys.get(level);
      if (key.line !== this.line || this.index - key.index > 1024) {
        if (key.required) {
          throw new ScannerError('while scanning a simple key', key.mark,
            "could not find expected ':'", this.getMark());
        }
        this.possibleSimpleKeys.delete(level);
      }
    }
  }

  savePossibleSimpleKey() {
    const required = this.flowLevel === 0 && this.indent === this.column;
    if (this.allowSimpleKey) {
      this.removePossibleSimpleKey();
      const tokenNumber = this.tokensTaken + this.tokens.length;
      const key = new SimpleKey(tokenNumber, required, this.index, this.line,
        this.column, this.getMark());
      this.possibleSimpleKeys.set(this.flowLevel, key);
    }
  }

  removePossibleSimpleKey() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      if (key.required) {
        throw new ScannerError('while scanning a simple key', key.mark,
          "could not find expected ':'", this.getMark());
      }
      this.possibleSimpleKeys.delete(this.flowLevel);
    }
  }

  // --- indentation ------------------------------------------------------

  unwindIndent(column) {
    if (this.flowLevel !== 0) return;
    while (this.indent > column) {
      const mark = this.getMark();
      this.indent = this.indents.pop();
      this.tokens.push(token(T.BLOCK_END, mark, mark));
    }
  }

  addIndent(column) {
    if (this.indent < column) {
      this.indents.push(this.indent);
      this.indent = column;
      return true;
    }
    return false;
  }

  // --- fetchers ---------------------------------------------------------

  fetchStreamStart() {
    const mark = this.getMark();
    this.tokens.push(token(T.STREAM_START, mark, mark, { encoding: null }));
  }

  fetchStreamEnd() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.possibleSimpleKeys = new Map();
    const mark = this.getMark();
    this.tokens.push(token(T.STREAM_END, mark, mark));
    this.done = true;
  }

  fetchDirective() {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanDirective());
  }

  fetchDocumentStart() { this.fetchDocumentIndicator(T.DOCUMENT_START); }
  fetchDocumentEnd() { this.fetchDocumentIndicator(T.DOCUMENT_END); }

  fetchDocumentIndicator(id) {
    this.unwindIndent(-1);
    this.removePossibleSimpleKey();
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward(3);
    const endMark = this.getMark();
    this.tokens.push(token(id, startMark, endMark));
  }

  fetchFlowSequenceStart() { this.fetchFlowCollectionStart(T.FLOW_SEQUENCE_START); }
  fetchFlowMappingStart() { this.fetchFlowCollectionStart(T.FLOW_MAPPING_START); }

  fetchFlowCollectionStart(id) {
    this.savePossibleSimpleKey();
    this.flowLevel += 1;
    this.allowSimpleKey = true;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(id, startMark, endMark));
  }

  fetchFlowSequenceEnd() { this.fetchFlowCollectionEnd(T.FLOW_SEQUENCE_END); }
  fetchFlowMappingEnd() { this.fetchFlowCollectionEnd(T.FLOW_MAPPING_END); }

  fetchFlowCollectionEnd(id) {
    this.removePossibleSimpleKey();
    this.flowLevel -= 1;
    this.allowSimpleKey = false;
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(id, startMark, endMark));
  }

  fetchFlowEntry() {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(T.FLOW_ENTRY, startMark, endMark));
  }

  fetchBlockEntry() {
    if (this.flowLevel === 0) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'sequence entries are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(token(T.BLOCK_SEQUENCE_START, mark, mark));
      }
    }
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(T.BLOCK_ENTRY, startMark, endMark));
  }

  fetchKey() {
    if (this.flowLevel === 0) {
      if (!this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping keys are not allowed here', this.getMark());
      }
      if (this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(token(T.BLOCK_MAPPING_START, mark, mark));
      }
    }
    this.allowSimpleKey = false;
    this.removePossibleSimpleKey();
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(T.KEY, startMark, endMark));
  }

  fetchValue() {
    if (this.possibleSimpleKeys.has(this.flowLevel)) {
      const key = this.possibleSimpleKeys.get(this.flowLevel);
      this.possibleSimpleKeys.delete(this.flowLevel);
      this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
        token(T.KEY, key.mark, key.mark));
      if (this.flowLevel === 0 && this.addIndent(key.column)) {
        this.tokens.splice(key.tokenNumber - this.tokensTaken, 0,
          token(T.BLOCK_MAPPING_START, key.mark, key.mark));
      }
      this.allowSimpleKey = false;
    } else {
      if (this.flowLevel === 0 && !this.allowSimpleKey) {
        throw new ScannerError(null, null,
          'mapping values are not allowed here', this.getMark());
      }
      if (this.flowLevel === 0 && this.addIndent(this.column)) {
        const mark = this.getMark();
        this.tokens.push(token(T.BLOCK_MAPPING_START, mark, mark));
      }
      this.allowSimpleKey = this.flowLevel === 0;
      this.removePossibleSimpleKey();
    }
    const startMark = this.getMark();
    this.forward();
    const endMark = this.getMark();
    this.tokens.push(token(T.VALUE, startMark, endMark));
  }

  fetchAlias() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(T.ALIAS));
  }

  fetchAnchor() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanAnchor(T.ANCHOR));
  }

  fetchTag() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanTag());
  }

  fetchLiteral() { this.fetchBlockScalar('|'); }
  fetchFolded() { this.fetchBlockScalar('>'); }

  fetchBlockScalar(style) {
    this.allowSimpleKey = true;
    this.removePossibleSimpleKey();
    this.tokens.push(this.scanBlockScalar(style));
  }

  fetchSingle() { this.fetchFlowScalar(SQUOTE); }
  fetchDouble() { this.fetchFlowScalar(DQUOTE); }

  fetchFlowScalar(style) {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanFlowScalar(style));
  }

  fetchPlain() {
    this.savePossibleSimpleKey();
    this.allowSimpleKey = false;
    this.tokens.push(this.scanPlain());
  }

  // --- checkers ---------------------------------------------------------

  checkDirective() {
    return this.column === 0;
  }

  checkDocumentStart() {
    return this.column === 0 && this.prefix(3) === '---'
      && inSet(NULL_BL_T_LINEBR, this.peek(3));
  }

  checkDocumentEnd() {
    return this.column === 0 && this.prefix(3) === '...'
      && inSet(NULL_BL_T_LINEBR, this.peek(3));
  }

  checkBlockEntry() {
    return inSet(NULL_BL_T_LINEBR, this.peek(1));
  }

  checkKey() {
    if (this.flowLevel !== 0) return true;
    return inSet(NULL_BL_T_LINEBR, this.peek(1));
  }

  checkValue() {
    if (this.flowLevel !== 0) return true;
    return inSet(NULL_BL_T_LINEBR, this.peek(1));
  }

  checkPlain() {
    const ch = this.peek();
    const forbidden = NULL_BL_T_LINEBR + '-?:,[]{}#&*!|>' + SQUOTE + DQUOTE + '%@`';
    if (!inSet(forbidden, ch)) return true;
    return !inSet(NULL_BL_T_LINEBR, this.peek(1))
      && (ch === '-' || (this.flowLevel === 0 && (ch === '?' || ch === ':')));
  }

  // --- scanners ---------------------------------------------------------

  scanToNextToken() {
    if (this.index === 0 && this.peek() === BOM) this.forward();
    let found = false;
    while (!found) {
      while (this.peek() === SPACE) this.forward();
      if (this.peek() === '#') {
        while (!inSet(NULL_OR_LINEBR, this.peek())) this.forward();
      }
      if (this.scanLineBreak() !== '') {
        if (this.flowLevel === 0) this.allowSimpleKey = true;
      } else {
        found = true;
      }
    }
  }

  scanDirective() {
    const startMark = this.getMark();
    this.forward();
    const name = this.scanDirectiveName(startMark);
    let value = null;
    let endMark;
    if (name === 'YAML') {
      value = this.scanYamlDirectiveValue(startMark);
      endMark = this.getMark();
    } else if (name === 'TAG') {
      value = this.scanTagDirectiveValue(startMark);
      endMark = this.getMark();
    } else {
      endMark = this.getMark();
      while (!inSet(NULL_OR_LINEBR, this.peek())) this.forward();
    }
    this.scanDirectiveIgnoredLine(startMark);
    return token(T.DIRECTIVE, startMark, endMark, { name, value });
  }

  scanDirectiveName(startMark) {
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + reprChar(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(NULL_BL_LINEBR, ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected alphabetic or numeric character, but found ' + reprChar(ch),
        this.getMark());
    }
    return value;
  }

  scanYamlDirectiveValue(startMark) {
    while (this.peek() === SPACE) this.forward();
    const major = this.scanYamlDirectiveNumber(startMark);
    if (this.peek() !== '.') {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        "expected a digit or '.', but found " + reprChar(this.peek()),
        this.getMark());
    }
    this.forward();
    const minor = this.scanYamlDirectiveNumber(startMark);
    if (!inSet(NULL_BL_LINEBR, this.peek())) {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        "expected a digit or ' ', but found " + reprChar(this.peek()),
        this.getMark());
    }
    return [major, minor];
  }

  scanYamlDirectiveNumber(startMark) {
    const ch = this.peek();
    if (!isDigit(ch)) {
      throw new ScannerError('while scanning a %YAML directive', startMark,
        'expected a digit, but found ' + reprChar(ch), this.getMark());
    }
    let length = 0;
    while (isDigit(this.peek(length))) length += 1;
    const value = Number(this.prefix(length));
    this.forward(length);
    return value;
  }

  scanTagDirectiveValue(startMark) {
    while (this.peek() === SPACE) this.forward();
    const handle = this.scanTagDirectiveHandle(startMark);
    while (this.peek() === SPACE) this.forward();
    const prefix = this.scanTagDirectivePrefix(startMark);
    return [handle, prefix];
  }

  scanTagDirectiveHandle(startMark) {
    const value = this.scanTagHandle('directive', startMark);
    const ch = this.peek();
    if (ch !== SPACE) {
      throw new ScannerError('while scanning a %TAG directive', startMark,
        "expected ' ', but found " + reprChar(ch), this.getMark());
    }
    return value;
  }

  scanTagDirectivePrefix(startMark) {
    const value = this.scanTagUri('directive', startMark);
    const ch = this.peek();
    if (!inSet(NULL_BL_LINEBR, ch)) {
      throw new ScannerError('while scanning a %TAG directive', startMark,
        "expected ' ', but found " + reprChar(ch), this.getMark());
    }
    return value;
  }

  scanDirectiveIgnoredLine(startMark) {
    while (this.peek() === SPACE) this.forward();
    if (this.peek() === '#') {
      while (!inSet(NULL_OR_LINEBR, this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!inSet(NULL_OR_LINEBR, ch)) {
      throw new ScannerError('while scanning a directive', startMark,
        'expected a comment or a line break, but found ' + reprChar(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanAnchor(id) {
    const startMark = this.getMark();
    const indicator = this.peek();
    const name = indicator === '*' ? 'alias' : 'anchor';
    this.forward();
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch)) {
      length += 1;
      ch = this.peek(length);
    }
    if (length === 0) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + reprChar(ch),
        this.getMark());
    }
    const value = this.prefix(length);
    this.forward(length);
    ch = this.peek();
    if (!inSet(NULL_BL_T_LINEBR + '?:,]}%@`', ch)) {
      throw new ScannerError('while scanning an ' + name, startMark,
        'expected alphabetic or numeric character, but found ' + reprChar(ch),
        this.getMark());
    }
    const endMark = this.getMark();
    return token(id, startMark, endMark, { value });
  }

  scanTag() {
    const startMark = this.getMark();
    let ch = this.peek(1);
    let handle;
    let suffix;
    if (ch === '<') {
      handle = null;
      this.forward(2);
      suffix = this.scanTagUri('tag', startMark);
      if (this.peek() !== '>') {
        throw new ScannerError('while parsing a tag', startMark,
          "expected '>', but found " + reprChar(this.peek()), this.getMark());
      }
      this.forward();
    } else if (inSet(NULL_BL_T_LINEBR, ch)) {
      handle = null;
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!inSet(NULL_BL_LINEBR, ch)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!inSet(NULL_BL_LINEBR, ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        "expected ' ', but found " + reprChar(ch), this.getMark());
    }
    const endMark = this.getMark();
    return token(T.TAG, startMark, endMark, { value: [handle, suffix] });
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      const res = this.scanBlockScalarIndentation();
      breaks = res[0];
      const maxIndent = res[1];
      endMark = res[2];
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
    }

    let lineBreak = '';
    while (this.column === indent && this.peek() !== NUL) {
      for (const b of breaks) chunks.push(b);
      const leadingNonSpace = this.peek() !== SPACE && this.peek() !== TAB;
      let length = 0;
      while (!inSet(NULL_OR_LINEBR, this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      const res = this.scanBlockScalarBreaks(indent);
      breaks = res[0];
      endMark = res[1];
      if (this.column === indent && this.peek() !== NUL) {
        if (folded && lineBreak === LF && leadingNonSpace
          && this.peek() !== SPACE && this.peek() !== TAB) {
          if (breaks.length === 0) chunks.push(SPACE);
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) for (const b of breaks) chunks.push(b);

    return token(T.SCALAR, startMark, endMark,
      { value: chunks.join(''), plain: false, style });
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0',
            this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0',
          this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!inSet(NULL_BL_LINEBR, ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected chomping or indentation indicators, but found ' + reprChar(ch),
        this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === SPACE) this.forward();
    if (this.peek() === '#') {
      while (!inSet(NULL_OR_LINEBR, this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!inSet(NULL_OR_LINEBR, ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        'expected a comment or a line break, but found ' + reprChar(ch),
        this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (inSet(SPACE + BREAKS, this.peek())) {
      if (this.peek() !== SPACE) {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === SPACE) this.forward();
    while (inSet(BREAKS, this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === SPACE) this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === DQUOTE;
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    while (this.peek() !== quote) {
      for (const c of this.scanFlowScalarSpaces(double, startMark)) chunks.push(c);
      for (const c of this.scanFlowScalarNonSpaces(double, startMark)) chunks.push(c);
    }
    this.forward();
    const endMark = this.getMark();
    return token(T.SCALAR, startMark, endMark,
      { value: chunks.join(''), plain: false, style });
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    const stop = SQUOTE + DQUOTE + BACKSLASH + NULL_BL_T_LINEBR;
    for (;;) {
      let length = 0;
      while (!inSet(stop, this.peek(length))) length += 1;
      if (length > 0) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === SQUOTE && this.peek(1) === SQUOTE) {
        chunks.push(SQUOTE);
        this.forward(2);
      } else if ((double && ch === SQUOTE)
        || (!double && (ch === DQUOTE || ch === BACKSLASH))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === BACKSLASH) {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          const count = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < count; k += 1) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar',
                startMark,
                'expected escape sequence of ' + count
                + ' hexdecimal numbers, but found ' + reprChar(this.peek(k)),
                this.getMark());
            }
          }
          const code = parseInt(this.prefix(count), 16);
          chunks.push(String.fromCodePoint(code));
          this.forward(count);
        } else if (inSet(BREAKS, ch)) {
          this.scanLineBreak();
          for (const c of this.scanFlowScalarBreaks(double, startMark)) chunks.push(c);
        } else {
          throw new ScannerError('while scanning a double-quoted scalar',
            startMark, 'found unknown escape character ' + reprChar(ch),
            this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === SPACE || this.peek(length) === TAB) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === NUL) {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    } else if (inSet(BREAKS, ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== LF) {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(SPACE);
      }
      for (const b of breaks) chunks.push(b);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...')
        && inSet(NULL_BL_T_LINEBR, this.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (this.peek() === SPACE || this.peek() === TAB) this.forward();
      if (inSet(BREAKS, this.peek())) {
        chunks.push(this.scanLineBreak());
      } else {
        return chunks;
      }
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      let length = 0;
      if (this.peek() === '#') break;
      for (;;) {
        const ch = this.peek(length);
        const flowStop = this.flowLevel !== 0 ? ',[]{}' : '';
        if (inSet(NULL_BL_T_LINEBR, ch)
          || (ch === ':' && inSet(NULL_BL_T_LINEBR + flowStop, this.peek(length + 1)))
          || (this.flowLevel !== 0 && inSet(',?[]{}', ch))) {
          break;
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      for (const s of spaces) chunks.push(s);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#'
        || (this.flowLevel === 0 && this.column < indent)) {
        break;
      }
    }
    return token(T.SCALAR, startMark, endMark,
      { value: chunks.join(''), plain: true, style: null });
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === SPACE) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (inSet(BREAKS, ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      let prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...')
        && inSet(NULL_BL_T_LINEBR, this.peek(3))) {
        return null;
      }
      const breaks = [];
      while (inSet(SPACE + BREAKS, this.peek())) {
        if (this.peek() === SPACE) {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          prefix = this.prefix(3);
          if ((prefix === '---' || prefix === '...')
            && inSet(NULL_BL_T_LINEBR, this.peek(3))) {
            return null;
          }
        }
      }
      if (lineBreak !== LF) {
        chunks.push(lineBreak);
      } else if (breaks.length === 0) {
        chunks.push(SPACE);
      }
      for (const b of breaks) chunks.push(b);
    } else if (whitespaces !== '') {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError('while scanning a ' + name, startMark,
        "expected '!', but found " + reprChar(ch), this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== SPACE) {
      while (isAlphaNumeric(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError('while scanning a ' + name, startMark,
          "expected '!', but found " + reprChar(ch), this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isAlphaNumeric(ch) || inSet(URI_EXTRA_CHARS, ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length > 0) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError('while parsing a ' + name, startMark,
        'expected URI, but found ' + reprChar(ch), this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const codes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError('while scanning a ' + name, startMark,
            'expected URI escape sequence of 2 hexdecimal numbers, but found '
            + reprChar(this.peek(k)), this.getMark());
        }
      }
      codes.push(parseInt(this.prefix(2), 16));
      this.forward(2);
    }
    try {
      return utf8Decode(codes);
    } catch (exc) {
      throw new ScannerError('while scanning a ' + name, startMark,
        exc.message, mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === CR || ch === LF || ch === NEL) {
      if (this.prefix(2) === CR + LF) {
        this.forward(2);
      } else {
        this.forward();
      }
      return LF;
    }
    if (ch === LS || ch === PS) {
      this.forward();
      return ch;
    }
    return '';
  }
}

/** Strict UTF-8 decode of a byte array, used for %XX escapes in tag URIs. */
export function utf8Decode(bytes) {
  let out = '';
  let i = 0;
  const fail = (start, reason) => {
    const err = new Error("'utf-8' codec can't decode byte 0x"
      + bytes[start].toString(16) + ' in position ' + start + ': ' + reason);
    throw err;
  };
  while (i < bytes.length) {
    const b0 = bytes[i];
    let code;
    let size;
    if (b0 < 0x80) { code = b0; size = 1; } else if (b0 >= 0xc2 && b0 <= 0xdf) { code = b0 & 0x1f; size = 2; } else if (b0 >= 0xe0 && b0 <= 0xef) { code = b0 & 0x0f; size = 3; } else if (b0 >= 0xf0 && b0 <= 0xf4) { code = b0 & 0x07; size = 4; } else {
      fail(i, 'invalid start byte');
    }
    if (i + size > bytes.length) fail(i, 'unexpected end of data');
    for (let k = 1; k < size; k += 1) {
      const b = bytes[i + k];
      if ((b & 0xc0) !== 0x80) fail(i, 'invalid continuation byte');
      code = (code << 6) | (b & 0x3f);
    }
    if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) {
      fail(i, 'invalid continuation byte');
    }
    out += String.fromCodePoint(code);
    i += size;
  }
  return out;
}

