/**
 * values.mjs -- the Python value model.
 *
 * `yaml.safe_load` produces Python objects and `yaml.dump` then dispatches on
 * their exact types, so the port needs types that are as distinguishable as
 * Python's.  The mapping is:
 *
 *   Python      JavaScript
 *   ------      ----------
 *   None        null
 *   bool        true / false
 *   int         BigInt            (arbitrary precision, like Python)
 *   float       number
 *   str         string
 *   bytes       PyBytes
 *   list        Array
 *   tuple       PyTuple
 *   dict        PyDict            (insertion ordered, Python key equality)
 *   set         PySet
 *   date        PyDate
 *   datetime    PyDateTime
 *
 * The module also implements Python's `<` ordering and CPython's list sort so
 * that `sort_keys=True` produces byte-identical key order, including the
 * TypeError that makes PyYAML fall back to insertion order.
 */

import { floatRepr } from './pyrepr.mjs';

/** Raised where CPython would raise TypeError. */
export class PyTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PyTypeError';
  }
}

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
  }
}

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2);
  }
}

export class PyDateTime {
  /** `tzMinutes` is null for a naive datetime, else the UTC offset. */
  constructor(year, month, day, hour, minute, second, microsecond, tzMinutes) {
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.tzMinutes = tzMinutes === undefined ? null : tzMinutes;
  }

  isoformat(sep = 'T') {
    let out = pad(this.year, 4) + '-' + pad(this.month, 2) + '-' + pad(this.day, 2)
      + sep + pad(this.hour, 2) + ':' + pad(this.minute, 2) + ':' + pad(this.second, 2);
    if (this.microsecond !== 0) out += '.' + pad(this.microsecond, 6);
    if (this.tzMinutes !== null) {
      const sign = this.tzMinutes < 0 ? '-' : '+';
      const abs = Math.abs(this.tzMinutes);
      out += sign + pad(Math.floor(abs / 60), 2) + ':' + pad(abs % 60, 2);
    }
    return out;
  }
}

function pad(value, width) {
  let s = String(value);
  while (s.length < width) s = '0' + s;
  return s;
}

/** Thrown when a value cannot be used as a dict key. */
export class Unhashable extends Error {
  constructor() {
    super('unhashable');
    this.name = 'Unhashable';
  }
}

let nanCounter = 0;

/**
 * A string that identifies a value the way Python's hash/eq pair does:
 * `1`, `1.0` and `True` all collapse to the same key, NaN never matches
 * anything (including itself), and containers are unhashable.
 */
export function hashKey(value) {
  if (value === null) return 'N';
  if (value === true) return 'i:1';
  if (value === false) return 'i:0';
  const type = typeof value;
  if (type === 'bigint') return 'i:' + value.toString();
  if (type === 'number') {
    if (Number.isNaN(value)) {
      nanCounter += 1;
      return 'nan:' + nanCounter;
    }
    if (Number.isInteger(value)) return 'i:' + BigInt(value).toString();
    return 'f:' + floatRepr(value);
  }
  if (type === 'string') return 's:' + value;
  if (value instanceof PyTuple) {
    return 't:' + value.items.length + ':'
      + value.items.map((item) => encodeURIComponent(hashKey(item))).join(',');
  }
  if (value instanceof PyBytes) {
    let hex = '';
    for (const b of value.bytes) hex += pad(b.toString(16), 2);
    return 'b:' + hex;
  }
  if (value instanceof PyDate) return 'D:' + value.isoformat();
  if (value instanceof PyDateTime) return 'T:' + value.isoformat();
  throw new Unhashable();
}

/** Insertion-ordered mapping with Python dict key semantics. */
export class PyDict {
  constructor() {
    this.map = new Map();
  }

  get size() { return this.map.size; }

  set(key, value) {
    const h = hashKey(key);
    const existing = this.map.get(h);
    if (existing !== undefined) {
      // Python keeps the original key object and replaces the value.
      existing.value = value;
      return;
    }
    this.map.set(h, { key, value });
  }

  has(key) { return this.map.has(hashKey(key)); }

  get(key) {
    const entry = this.map.get(hashKey(key));
    return entry === undefined ? undefined : entry.value;
  }

  *entries() {
    for (const entry of this.map.values()) yield [entry.key, entry.value];
  }

  items() {
    return Array.from(this.entries());
  }
}

/** Insertion-ordered set with Python set key semantics. */
export class PySet {
  constructor() {
    this.map = new Map();
  }

  get size() { return this.map.size; }

