/**
 * resolver.mjs -- implicit tag resolution for plain scalars.
 *
 * PyYAML drives this from compiled regular expressions keyed by the scalar's
 * first character.  This port keeps the exact same dispatch table and
 * alternative ordering but recognises each pattern with a hand written
 * character matcher, so no regular-expression machinery is involved.
 *
 * Python's `$` also matches immediately before a single trailing newline, so
 * every matcher is applied to the value with one trailing LF removed while the
 * first-character dispatch still uses the original string.
 */

import { NodeKind } from './nodes.mjs';
import { LF, isDigit, isHexDigit } from './chars.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

export const TAG = {
  NULL: 'tag:yaml.org,2002:null',
  BOOL: 'tag:yaml.org,2002:bool',
  INT: 'tag:yaml.org,2002:int',
  FLOAT: 'tag:yaml.org,2002:float',
  STR: 'tag:yaml.org,2002:str',
  TIMESTAMP: 'tag:yaml.org,2002:timestamp',
  MERGE: 'tag:yaml.org,2002:merge',
  VALUE: 'tag:yaml.org,2002:value',
  YAML: 'tag:yaml.org,2002:yaml',
  BINARY: 'tag:yaml.org,2002:binary',
  SEQ: 'tag:yaml.org,2002:seq',
  MAP: 'tag:yaml.org,2002:map',
  SET: 'tag:yaml.org,2002:set',
  OMAP: 'tag:yaml.org,2002:omap',
  PAIRS: 'tag:yaml.org,2002:pairs',
  PYTHON_TUPLE: 'tag:yaml.org,2002:python/tuple',
};

// --- small cursor helpers ----------------------------------------------

/** Cursor over a string with the primitives the matchers need. */
class Cursor {
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  get atEnd() { return this.pos >= this.text.length; }
  peek(offset = 0) { return this.text[this.pos + offset]; }

  /** Consume `ch` if present. */
  eat(ch) {
    if (this.text[this.pos] === ch) {
      this.pos += 1;
      return true;
    }
    return false;
  }

  /** Consume one character from `set` if present. */
  eatAnyOf(set) {
    const ch = this.text[this.pos];
    if (ch !== undefined && set.indexOf(ch) !== -1) {
      this.pos += 1;
      return ch;
    }
    return null;
  }

  /** Consume characters accepted by `pred`; returns how many. */
  eatWhile(pred) {
    let count = 0;
    while (this.pos < this.text.length && pred(this.text[this.pos])) {
      this.pos += 1;
      count += 1;
    }
    return count;
  }

  /** Consume exactly `count` characters accepted by `pred`. */
  eatExactly(count, pred) {
    if (this.pos + count > this.text.length) return false;
    for (let i = 0; i < count; i += 1) {
      if (!pred(this.text[this.pos + i])) return false;
    }
    this.pos += count;
    return true;
  }

