/**
 * composer.mjs -- turns the event stream into a node graph.
 *
 * Faithful port of PyYAML's `yaml/composer.py`.
 */

import { Parser } from './parser.mjs';
import { ComposerError } from './errors.mjs';
import { E } from './events.mjs';
import { ScalarNode, SequenceNode, MappingNode, NodeKind } from './nodes.mjs';
import { resolver } from './resolver.mjs';
import { reprString } from './pyrepr.mjs';

export class Composer {
  constructor(stream) {
    this.parser = new Parser(stream);
    this.anchors = new Map();
  }

  checkEvent(...choices) { return this.parser.checkEvent(...choices); }
  peekEvent() { return this.parser.peekEvent(); }
  getEvent() { return this.parser.getEvent(); }

  checkNode() {
    if (this.checkEvent(E.STREAM_START)) this.getEvent();
